{
  "themes": [
    {
      "cluster": 24,
      "name": "Frequent Buggy Updates",
      "description": "Customers complain that each new update introduces bugs, causing crashes and unstable behavior."
    },
    {
      "cluster": 25,
      "name": "Premium Required for Full Playback",
      "description": "Users are frustrated that songs are only partially playable or limited unless they purchase premium."
    },
    {
      "cluster": 26,
      "name": "Random Song Playback Instead of Selected Track",
      "description": "Listeners report the app plays unrelated or random songs when they try to play a specific track or playlist."
    },
    {
      "cluster": 27,
      "name": "App Crashes During Playback",
      "description": "The application repeatedly crashes when users switch playlists, select songs, or simply try to play music."
    },
    {
      "cluster": 28,
      "name": "Excessive Advertising in Free Version",
      "description": "Free users find the number and length of ads overly intrusive and disruptive to listening."
    },
    {
      "cluster": 29,
      "name": "Positive Perception of Premium Value",
      "description": "Customers express that the premium subscription is worth the cost and improves their experience."
    },
    {
      "cluster": 30,
      "name": "Incorrect Song Substitution",
      "description": "When a user selects a song, the app often plays a different, unrelated track instead."
    },
    {
      "cluster": 31,
      "name": "Missing Bulk Playlist Management Features",
      "description": "Users request the ability to add multiple songs to playlists at once and create shared liked‑song playlists."
    },
    {
      "cluster": 32,
      "name": "Ad Frequency Increased After Updates",
      "description": "Long‑time users notice a surge in ad count and duration following recent app updates."
    },
    {
      "cluster": 33,
      "name": "Playback Stops Unexpectedly",
      "description": "Songs frequently halt after a few seconds or after finishing, requiring a restart or airplane‑mode toggle."
    },
    {
      "cluster": 34,
      "name": "Ads Every Few Songs for Free Users",
      "description": "Non‑premium listeners are annoyed by ads that appear after every two or three songs."
    },
    {
      "cluster": 35,
      "name": "Premium Appreciated but Still Ads Present",
      "description": "Even premium subscribers notice occasional ads and wish for completely ad‑free listening."
    }
  ]
}
